def solve(nums, target):
    def find(left, right):
        if left > right: return -1
        mid = (left + right) // 2
        if nums[mid] == target: return mid
        if nums[mid] < target: return find(mid + 1, right)
        return find(left, mid - 1)
    return find(0, len(nums) - 1)

